def find_path(graph, start, goal):
    # Initialize the predecessor cache and the seen set
    predecessor_cache = {start: None}
    seen = set([start])

    # Initialize the queue with the start node
recurse = [start]
    while recurse:
        node = recurse.pop(0)

        # If we have reached the goal, we can start reconstructing the path
        if node == goal:
            path = []
            while node:
                path.append(node)
                node = predecessor_cache[node]
            return path[::-1]

        # Explore all neighbors of the current node
        for neighbor in graph[node]:
            if neighbor not in seen:
                seen.add(neighbor)
                predecessor_cache[neighbor] = node
                recurse.append(neighbor)

    # If we have exhausted all possible paths and haven't found the goal, return None
    return None

