def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None
    path_memory = {}

    def search(node, previous_node=None):
        if node == goal:
            return [node]
        if node in path_memory:
            return path_memory[node]
        for neighbor in graph[node]:
            if neighbor == previous_node:
                continue
            path = search(neighbor, node)
            if path:
                path_memory[node] = [node] + path
                return path_memory[node]
        path_memory[node] = []
        return None
    return search(start)
